%dw 2.0
output application/json
---
{
  "getCoverageOPOutput": {
    "wsResponseHeader2": {
      "system": {
        "name": "Mulesoft",  
        "correlationID": vars.correlationId, 
        "processingServer": "Mulesoft" 
      },
      "service": {
        "status": "FAIL", 
        "responseDate": now(), 
        "statusDetail": {
          "errorCode": "COVERR02",
          "errorMessage": "Dirección sin cobertura FTTC|FTTH"  
        }
      }
    }
  }
}

%dw 2.0
output application/json
---
{
  "getCoverageOPOutput": {
    "wsResponseHeader2": {
      "system": {
        "name": "Mulesoft",  
        "correlationID": vars.correlationId, 
        "processingServer": "Mulesoft" 
      },
      "service": {
        "status": "FAIL", 
        "responseDate": now(), 
        "statusDetail": {
          "errorCode": if(payload.feasibilityResponse.outputMessage.'M6ConsultarBloquearRecursos-RS'.RespuestaFactibilidad.Factible == "NO FACTIBLE") "COVERR03" else "COVERR06",
          "errorMessage": payload.feasibilityResponse.outputMessage.'M6ConsultarBloquearRecursos-RS'.RespuestaFactibilidad.Motivo
        }
      }
    }
  }
}

