%dw 2.0
output application/json
---
{
  "getCoverageOPOutput": {
    "wsResponseHeader2": {
      "system": {
        "name": "Mulesoft", 
        "correlationID": vars.correlationId, 
        "processingServer": "Mulesoft",
        },
      "service": {
        "status": "PASS", 
        "responseDate": vars.dateTime
      }
    },
    "getCoverageResponse": {
      "address":[
        {
          "geoState": vars.response1.outputMessage."WSGeorreferenciarCR-RS".EstadoGeo as String, 
          "addressCode": vars.response1.outputMessage."WSGeorreferenciarCR-RS".CodigoDireccion as String,
          "latitude": vars.response1.outputMessage."WSGeorreferenciarCR-RS".Latitud as String, 
          "length": vars.response1.outputMessage."WSGeorreferenciarCR-RS".Longitud as String, 
          "stratum": vars.response1.outputMessage."WSGeorreferenciarCR-RS".Estrato as Number, 
          "lotCode": vars.response1.outputMessage."WSGeorreferenciarCR-RS".CodigoLote as String, 
          "destiny": vars.response1.outputMessage."WSGeorreferenciarCR-RS".Destino as String, 
          "chip": vars.response1.outputMessage."WSGeorreferenciarCR-RS".Chip as String, 
          "district": vars.response1.outputMessage."WSGeorreferenciarCR-RS".Barrio as String,
          "location": vars.response1.outputMessage."WSGeorreferenciarCR-RS".Localidad default "",  
          "distanceType": vars.response1.outputMessage."WSGeorreferenciarCR-RS".TipoDistancia, 
          "distanceType2": if(vars.valorHomologacion != null) vars.valorHomologacion else "" as String
        }
      ],
      "coverage":[
        {
          "technology": 
          vars.response3."wsGetFactibilidadServicios-RS".Tecnologias.Tecnologia map (obj,ind) ->{
            "type": obj.Tipo,
            "coverageType": obj.TipoCobertura, 
            "coverage": obj.Cobertura,
            "coverageName": obj.NombreCobertura,
            "areaType": obj.TipoArea,
            "area": obj.Area

            }
        }
      ]
    }
  }
}
